$maxAttempts = 60
for ($i = 1; $i -le $maxAttempts; $i++) {
    Write-Host "[$(Get-Date -Format 'HH:mm:ss')] Attempt $i/$maxAttempts..."
    $result = ssh -o ConnectTimeout=10 mx "echo CONNECTED" 2>&1
    if ($result -match "CONNECTED") {
        Write-Host "SSH CONNECTED! Uploading and launching autonomous pipeline..."
        $scriptBytes = [Convert]::FromBase64String("")
        $scriptText = [Text.Encoding]::UTF8.GetString($scriptBytes)
        $scriptText | ssh -o ConnectTimeout=10 mx "cat > /tmp/run_r3_1_autonomous.sh && sed -i 's/\r\$//' /tmp/run_r3_1_autonomous.sh && chmod +x /tmp/run_r3_1_autonomous.sh && nohup bash /tmp/run_r3_1_autonomous.sh > /mnt/storage_pool/liaoyuanjun/r3_1_pipeline_nohup.log 2>&1 & echo LAUNCHED"
        Write-Host "Pipeline launched!"
        break
    }
    Write-Host "  Failed, waiting 120s..."
    Start-Sleep -Seconds 120
}
